7	/**
8	 * Step of the owner pipelines that validates the optional postcode against the owner's city region.
9	 * A postcode is validated only WHEN PRESENT: an absent (null/blank) postcode passes untouched, so
10	 * an owner supplied without a postcode is still accepted. When present it must be 4 digits and, for
11	 * a city with a known region, within that region's range (see {@link Postcode}); otherwise
12	 * {@link InvalidPostcodeException} is thrown (handled as 400).
13	 */
14	public class RequirePostcode {
15	
16	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
17	        Postcode.validate(request.getPostcode(), request.getCity());
18	    }
19	}
