1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
7	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
8	
9	public class ApplyOwner {
10	
11	    public void service(@Val Owner owner, @Val OwnerFieldsDto request)
12	            throws InvalidEmailException, InvalidTelephoneException {
13	        owner.setAddress(request.getAddress());
14	        owner.setCity(request.getCity());
15	        owner.setFirstName(request.getFirstName());
16	        owner.setLastName(request.getLastName());
17	        owner.setTelephone(OwnerTelephone.toE164(request.getTelephone()));
18	        owner.setEmail(OwnerEmail.normalize(request.getEmail()));
19	        owner.setPostcode(request.getPostcode());
20	    }
21	}
